#ifndef WS_CONTAINERS_BLOCK_DEQUE_H
#define WS_CONTAINERS_BLOCK_DEQUE_H

#include <deque>
#include <chrono>
#include <mutex>
#include <condition_variable>

template <typename T>
class BlockDeque {
public:
    BlockDeque(size_t capacity) : capacity_(capacity) {}

    void PushBack(const T& item);
    T PopFront();
    bool Empty() const;
    size_t Size() const;
    size_t Capacity() const { return capacity_; }

private:
    std::deque<T> deque_; 
    size_t capacity_; 
    std::mutex mtx_; 
    std::condition_variable cv_; 
};

template <typename T>
class BlockDeque<T>::Clock {
public:
    using clock = std::chrono::steady_clock;
};

