#ifndef WS_CONFIG_H
#define WS_CONFIG_H

#include <string>
#include <memory>
#include <list>
#include <functional>
#include <type_traits>

namespace ws {
namespace cfg {

// Forward declaration for From and To types.
template <typename From, typename To> class VarConverter;

class VarBase {
public:
    virtual ~VarBase() = default;
    virtual std::string Name() const = 0;
    virtual std::string Description() const = 0;
};

template <typename T, typename FromStr, typename ToStr> class Var : public VarBase {
public:
    Var(const std::string& name, const std::string& description) : name_(name), description_(description) {}
    std::string Name() const override { return name_; }
    std::string Description() const override { return description_; }

private:
    std::string name_;
    std::string description_;
};

template <typename T, typename... Args> class Singleton {
public:
    static T& Instance() {
        static T instance(Args...);
        return instance;
    }

private:
    Singleton() = default;
    Singleton(const Singleton&) = delete;
    Singleton& operator=(const Singleton&) = delete;
};

template <typename T, typename... Args> class SingletonPtr {
public:
    static std::shared_ptr<T> Instance() {
        static auto instance = std::make_shared<T>(Args...);
        return instance;
    }

private:
    SingletonPtr() = default;
};

template <typename T, typename Cleaner> class RAII {
public:
    RAII(Cleaner cleaner) : cleaner_(cleaner) {}
    ~RAII() { cleaner_(); }

private:
    Cleaner cleaner_;  // Function object to clean up the resource.
};

class MappedReadOnlyFile {
public:
    MappedReadOnlyFile(const std::string& filename) {}
    ~MappedReadOnlyFile() {}

private:
};

}
}

#endif // WS_CONFIG_H

void ws::cfg::VarConverter<std::string, int>::Convert(const std::string& from, int& to) {
  try {
    to = std::stoi(from);
  } catch (const std::invalid_argument& e) {
    throw;
  }
}

void ws::cfg::VarConverter<int, std::string>::Convert(const int& from, std::string& to) {
  to = std::to_string(from);
}
